'use strict';
const cp=require('node:child_process'),P=require('./policy.cjs');
const MAX_LOG=64*1024*1024;
function environment(v,extra={}){const out={};for(const k of ['PATH','HOME','SHELL','TMPDIR','LANG','LC_ALL','DEVELOPER_DIR','GEM_HOME','GEM_PATH'])if(typeof v[k]==='string')out[k]=v[k];return {...out,CI:'1',EXPO_NO_TELEMETRY:'1',EXPO_NO_DOCTOR:'1',FASTLANE_SKIP_UPDATE_CHECK:'1',FASTLANE_OPT_OUT_USAGE:'1',COCOAPODS_DISABLE_STATS:'true',...extra};}
function run(file,args,options,ports={}){if(typeof file!=='string'||!Array.isArray(args)||args.some(x=>typeof x!=='string')||!P.exact(options,['cwd','env','timeoutMs'])||!Number.isSafeInteger(options.timeoutMs)||options.timeoutMs<1||options.timeoutMs>7200000)P.fail();return new Promise((resolve,reject)=>{let child,total=0,ended=false,t,killer,bad=false;const out=[],err=[],spawn=ports.spawn||cp.spawn,timer=ports.setTimeout||setTimeout,clear=ports.clearTimeout||clearTimeout;const kill=signal=>{try{if(!ports.spawn&&process.platform!=='win32')process.kill(-child.pid,signal);else child.kill(signal);}catch{}};const finish=(error,status,signal)=>{if(ended)return;ended=true;if(t!==undefined)clear(t);if(killer!==undefined)clear(killer);resolve({status:Number.isInteger(status)?status:null,error:!!(error||bad),signal:signal||null,stdout:Buffer.concat(out),stderr:Buffer.concat(err)});};try{child=spawn(file,args,{cwd:options.cwd,env:options.env,shell:false,stdio:['ignore','pipe','pipe'],windowsHide:true,detached:process.platform!=='win32'});t=timer(()=>{bad=true;kill('SIGTERM');killer=timer(()=>{if(!ended)kill('SIGKILL');},1000);},options.timeoutMs);for(const [stream,bits]of [[child.stdout,out],[child.stderr,err]])stream.on('data',b=>{if(ended||bad)return;if(!Buffer.isBuffer(b)||(total+=b.length)>MAX_LOG){bad=true;kill('SIGKILL');}else bits.push(b);});child.on('error',()=>finish(true,null,null));child.on('close',(code,signal)=>finish(false,code,signal));}catch{if(t!==undefined)clear(t);reject(Error('PRIVATE_CHILD_REFUSED'));}});}
module.exports={MAX_LOG,environment,run};
